import {createHash} from 'node:crypto';
import Ajv from 'ajv';
import {scanOriginalTurn} from './turn-recovery.js';
import type {CodexRecoveryReader} from './turn-recovery.js';

// Generated by codex-cli 0.171.0-alpha.13 using app-server generate-json-schema.
// Pin the original bytes so recovery never compiles a model-provided schema.
const digests = {
  'thread/read':
    'e00173a4037e7492b2c1aaef52834706d60de5201b692f5686777c49fa0d43e1',
  'thread/turns/list':
    '7697e695b32ac9480d301e37d9c7c53fa7b227afa535ece31eced2f28e3a0d47',
  'thread/items/list':
    '86baff11ba4eb7809a3cf88c1781bff7a724758eb3ed91a08dd6eb7ae8f221e4',
} as const;
type Method = keyof typeof digests;

function checker() {
  const ajv = new Ajv({ownProperties: true, logger: false});
  // JavaScript cannot represent every wire-level 64-bit integer exactly.
  // Decline evidence outside the lossless range.
  const bounds: Record<string, readonly [number, number]> = {
    uint8: [0, 255],
    uint16: [0, 65535],
    uint32: [0, 4294967295],
    int32: [-2147483648, 2147483647],
    uint: [0, Number.MAX_SAFE_INTEGER],
    uint64: [0, Number.MAX_SAFE_INTEGER],
    int64: [Number.MIN_SAFE_INTEGER, Number.MAX_SAFE_INTEGER],
  };
  for (const [name, [min, max]] of Object.entries(bounds)) {
    ajv.addFormat(name, {
      type: 'number',
      validate: (value: number) =>
        Number.isSafeInteger(value) && value >= min && value <= max,
    });
  }
  return ajv;
}

/** Build once for a qualified binary, using the three unmodified v2 reply
 * schemas generated by that binary. An absent or mismatched schema disables
 * recovery. The returned operation has no write or resume capability. */
export function qualifyCodexRecovery(
  schemas: Readonly<Record<Method, Uint8Array>>,
) {
  const checks = new Map<Method, Ajv.ValidateFunction>();
  try {
    const ajv = checker();
    for (const method of Object.keys(digests) as Method[]) {
      if (schemas[method].byteLength > 128 * 1024) return undefined;
      const bytes = Buffer.from(schemas[method]);
      if (createHash('sha256').update(bytes).digest('hex') !== digests[method])
        return undefined;
      const schema: unknown = JSON.parse(bytes.toString('utf8'));
      if (!schema || typeof schema !== 'object' || Array.isArray(schema))
        return undefined;
      checks.set(method, ajv.compile(schema));
    }
  } catch {
    return undefined;
  }
  return (reader: CodexRecoveryReader, threadId: string, clientId: string) =>
    scanOriginalTurn(
      reader,
      threadId,
      clientId,
      (method, value) => checks.get(method)?.(value) === true,
    );
}
